{"implementation":"def solve(case):
    segments = case["segments"]
    budget = int(case["budget"])

    allocations = [int(segment["minimum"]) for segment in segments]
    remaining = max(0, budget - sum(allocations))

    order = sorted(
        range(len(segments)),
        key=lambda index: (-int(segments[index]["importance"]), index),
    )

    for index in order:
        if remaining == 0:
            break
        capacity = int(segments[index]["capacity"])
        available = max(0, capacity - allocations[index])
        added = min(remaining, available)
        allocations[index] += added
        remaining -= added

    by_name = {
        segment["name"]: allocations[index]
        for index, segment in enumerate(segments)
    }

    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": sum(allocations),
    }
"}
